const sample=(buffer:AudioBuffer,channel:number,seconds:number)=>buffer.getChannelData(channel)[Math.round(seconds*rate)];
const listenerParams=(context:BaseAudioContext)=>['positionX','positionY','positionZ','forwardX','forwardY','forwardZ','upX','upY','upZ'].map(name=>Reflect.get(context.listener,name)?.value);
