async function directPanner(blob:Blob,position:Vec,model:'equalpower'|'HRTF',seconds=1){const context=new OfflineAudioContext(2,Math.round(seconds*rate),rate),buffer=await context.decodeAudioData(await blob.arrayBuffer()),source=context.createBufferSource(),panner=context.createPanner();source.buffer=buffer;panner.panningModel=model;panner.distanceModel='inverse';panner.refDistance=1;panner.maxDistance=10000;panner.rolloffFactor=0;panner.positionX.value=position.x;panner.positionY.value=position.y;panner.positionZ.value=position.z;source.connect(panner);panner.connect(context.destination);source.start();const out=await context.startRendering();source.disconnect();panner.disconnect();return out;}
