const until=async(check:()=>boolean,message:string)=>{for(let i=0;i<100;i++){if(check())return;await act(async()=>{await new Promise(resolve=>setTimeout(resolve,10));});}throw Error(message);};
async function databaseSnapshot(){async function encode(value:unknown):Promise<unknown>{if(value===undefined)return['undefined'];if(value===null)return['null'];if(value instanceof Blob)return['blob',value.type,value.size,[...new Uint8Array(await crypto.subtle.digest('SHA-256',await value.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('')];if(value instanceof Date)return['date',value.getTime()];if(Array.isArray(value))return['array',await Promise.all(value.map(encode))];if(record(value)){const output:unknown[]=[];for(const key of Object.keys(value).sort())output.push([key,await encode(value[key])]);return['object',output];}return[typeof value,value];}const result:Record<string,unknown>={};for(const table of db.tables)result[table.name]=await encode(await table.toArray());return JSON.stringify(result);}
const sourceDefinition=()=>defineLocalTool({namespace:'qa.spatial-owner',name:{en:'Spatial audio',es:'Audio espacial'},description:{en:'Own synthetic audio fixture',es:'Prueba propia'},initialState:{},validateState:(value:LocalToolJson):value is Record<string,LocalToolJson>=>record(value),component:SoundPad});
const project=(id:string)=>({id,title:'Own spatial audio QA',description:'Synthetic only',mode:'custom' as const,type:'standalone' as const,status:'draft' as const,color:'#777777',enabledEngines:['writings'],engineOrder:['writings'],createdAt:1,updatedAt:1});
async function bridge(name:string,args:Record<string,unknown>){const reply=await runBridgeTool(name,args);assert(reply.ok,name+': '+JSON.stringify(reply));assert(record(reply.result),'Expected normal dispatcher object');return reply.result;}
