export async function testAudioSpatialOwnerCoordinatorHandles(){
 const id='spatial-handles-'+crypto.randomUUID(),aScene=scene(wav(.25,2)),bScene=scene(wav(.125,2)),clients:ReturnType<typeof createLocalToolClient>[]=[];
 try{await createProject(project(id));const asset=await importLocalMedia(id,new File([wav(.25,2)],'own-two-coordinators.wav',{type:'audio/wav'})),definition=sourceDefinition(),a=createLocalToolClient(id,definition,{audioEngine:aScene.engine}),b=createLocalToolClient(id,definition,{audioEngine:bScene.engine});clients.push(a,b);const aa=a.audio!,ba=b.audio!,before=await databaseSnapshot(),ar={x:-1,y:0,z:0},br={x:1,y:0,z:0},next=spatial({x:0,y:0,z:-1},'HRTF',0),aid=await Reflect.apply(aa.play,aa,[{kind:'media',id:asset.id},{spatial:spatial(ar)}]),bid=await Reflect.apply(ba.play,ba,[{kind:'media',id:asset.id},{spatial:spatial(br)}]);assert(typeof aid==='string'&&typeof bid==='string','Both normal coordinator voices must start');const priorA=call(aa,'getSpatial',aid),starts=[aScene.stats.starts,bScene.stats.starts],reply=await bridge('wh_local_audio_control',{projectId:id,action:'spatial',handleId:bid,spatial:next}),afterA=call(aa,'getSpatial',aid),afterB=call(ba,'getSpatial',bid);console.log('AUDIO_SPATIAL_COORDINATOR_HANDLES '+JSON.stringify({aid,bid,distinct:aid!==bid,reply,priorA,afterA,afterB,startsBefore:starts,startsAfter:[aScene.stats.starts,bScene.stats.starts]}));equal('Exact second handle control must preserve first coordinator',afterA,priorA);equal('Second coordinator receives requested spatial config',afterB,next);assert(aid!==bid,'Opaque voice IDs collide across registered coordinators');equal('Second spatial control keeps both original sources',[aScene.stats.starts,bScene.stats.starts],starts);
  await bridge('wh_local_audio_control',{projectId:id,action:'pan',handleId:bid,pan:1});equal('Pan exact second only',[aa.getState()[0].pan,ba.getState()[0].pan],[0,1]);await bridge('wh_local_audio_control',{projectId:id,action:'pause',handleId:bid});equal('Pause exact second only',[aa.getState()[0].status,ba.getState()[0].status],['playing','paused']);await bridge('wh_local_audio_control',{projectId:id,action:'stop',handleId:bid});equal('Stop exact second only',[aa.getState().map(row=>row.id),ba.getState()],[ [aid],[] ]);equal('Cross-coordinator runtime controls preserve all DB rows/Blobs',await databaseSnapshot(),before);return ['Two public host clients with distinct coordinators in the SAME project/era obtain unique opaque first-voice IDs; spatial/pan/pause/stop select the exact second voice and preserve the first without restart'];
 }finally{for(const client of clients)client.audio?.dispose();if(await db.projects.get(id))await deleteProject(id);assert((await Promise.all(db.tables.map(table=>table.count()))).every(n=>n===0),'Own coordinator fixture leaves rows');}
}


import Modal from '@/components/common/Modal';
import {useState as useSpatialModalState} from 'react';
/** Actual Modal's document-bubble Escape plus the real normal SoundPad fields. */
export async function testAudioSpatialOwnerEscapeInModal(){
 const projectId='spatial-modal-'+crypto.randomUUID(),s=scene(wav(.25,2)),host=document.getElementById('root')!,root=createRoot(host);let closes=0,escaped=0,entered=0,mounted=false;
 const outside=(event:KeyboardEvent)=>{if(event.key==='Escape')escaped++;if(event.key==='Enter')entered++;};
 await createProject(project(projectId));const client=createLocalToolClient(projectId,sourceDefinition(),{audioEngine:s.engine}),audio=client.audio!;
 function Mounted(){const [open,setOpen]=useSpatialModalState(true);useLocalToolAudioLifecycle(audio);return <Modal open={open} title="Own spatial keyboard QA" onClose={()=>{closes++;setOpen(false);}}><SoundPad client={client} projectId={projectId}/></Modal>;}
 const dialog=()=>document.querySelector<HTMLElement>('[role="dialog"]'),button=(text:string)=>[...dialog()!.querySelectorAll<HTMLButtonElement>('button')].find(node=>node.textContent===text)!;
 const input=()=>dialog()!.querySelector<HTMLInputElement>('input[aria-label="Emitter X (m)"]')!;
 const type=async(node:HTMLInputElement,value:string)=>{await act(async()=>{node.focus();node.dispatchEvent(new FocusEvent('focusin',{bubbles:true}));Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value')!.set!.call(node,value);node.dispatchEvent(new Event('input',{bubbles:true}));node.dispatchEvent(new Event('change',{bubbles:true}));});await act(async()=>{root.render(<StrictMode><Mounted/></StrictMode>);});assert(input()===node&&node.value===value,'Keyboard case must keep same input and actual controlled React draft');};
 try{useLocaleStore.setState({locale:'en',loaded:true});await importLocalMedia(projectId,new File([wav(.25,2)],'own-modal.wav',{type:'audio/wav'}));const before=await databaseSnapshot();await act(async()=>{root.render(<StrictMode><Mounted/></StrictMode>);mounted=true;await tick();});await until(()=>!!dialog()?.querySelector('select[aria-label="Local sound"] option'),'Actual modal/SoundPad media not ready');document.addEventListener('keydown',outside);
  const mode=dialog()!.querySelector<HTMLSelectElement>('select[aria-label="Audio mode"]')!;await act(async()=>{Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value')!.set!.call(mode,'HRTF');mode.dispatchEvent(new Event('change',{bubbles:true}));});await act(async()=>{button('Play effect').click();await tick();});await until(()=>audio.getState()[0]?.status==='playing','Actual modal example Play absent');const id=audio.getState()[0].id;await act(async()=>{button('Pause').click();});const saved=call(audio,'getSpatial',id),x=input();
  await type(x,'-');await act(async()=>{x.blur();x.dispatchEvent(new FocusEvent('focusout',{bubbles:true}));});assert(x.getAttribute('aria-invalid')==='true'&&dialog()!.querySelector('[role="alert"]'),'Invalid coordinate draft must be visible before Escape');equal('Invalid draft does not change admitted audio',call(audio,'getSpatial',id),saved);
  const escape=new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true});await act(async()=>{x.focus();x.dispatchEvent(new FocusEvent('focusin',{bubbles:true}));x.dispatchEvent(escape);});console.log('AUDIO_SPATIAL_MODAL_ESCAPE '+JSON.stringify({closes,externalEscapes:escaped,defaultPrevented:escape.defaultPrevented,dialogPresent:!!dialog(),value:x.value,invalid:x.getAttribute('aria-invalid'),spatial:call(audio,'getSpatial',id)}));equal('Coordinate Escape must not reach actual Modal or document listener',[closes,escaped],[0,0]);assert(dialog()?.contains(x)&&input()===x,'Coordinate Escape closed or replaced the actual edit dialog');equal('Escape restores admitted value and clears validation',[x.value,x.getAttribute('aria-invalid'),call(audio,'getSpatial',id)],['0',null,saved]);assert(escape.defaultPrevented,'Escape must consume its default');
  await type(x,'-2');const enter=new KeyboardEvent('keydown',{key:'Enter',bubbles:true,cancelable:true});await act(async()=>{x.dispatchEvent(enter);x.dispatchEvent(new FocusEvent('focusout',{bubbles:true}));});assert(enter.defaultPrevented,'Coordinate Enter must retain default prevention');equal('Enter commits through normal blur without closing',[closes,x.value,audio.getState()[0].id,audio.getState()[0].status],[0,'-2',id,'paused']);const next=call(audio,'getSpatial',id);assert(record(next),'Admitted spatial config missing');equal('Enter applies exact coordinate',next.position,{x:-2,y:0,z:-1});assert(entered===1,'Enter propagation is otherwise unchanged');equal('Keyboard editing does not persist any DB/Blob',await databaseSnapshot(),before);
  await act(async()=>{dialog()!.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true}));});equal('Escape outside coordinate still closes normal Modal',[closes,escaped,!!dialog()],[1,1,false]);return ['Real Modal document-bubble Escape is consumed only by the coordinate: invalid draft restores the admitted value and clears alert without closing, replacing input or touching runtime audio/DB','Enter retains default prevention and commits on normal blur with same paused handle; external Escape still closes Modal. Hidden-window focus events are explicit; this does not claim native implicit-submit or Brave gesture evidence'];
 }finally{document.removeEventListener('keydown',outside);if(mounted)await act(async()=>{root.unmount();await tick();});audio.dispose();if(await db.projects.get(projectId))await deleteProject(projectId);assert((await Promise.all(db.tables.map(table=>table.count()))).every(n=>n===0),'Own keyboard fixture leaves rows');}
}
